using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Volo.Abp.Cli.Commands;
using Volo.Abp.Cli.Args;

namespace Volo.Abp.Cli.Tests
{
    public class GenerateRazorPageTests
    {
        [Fact]
        public async Task ExecuteAsync_Should_LogInformation_With_Correct_Message()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<GenerateRazorPage>>();
            var command = new GenerateRazorPage
            {
                Logger = loggerMock.Object
            };

            // Setup a dummy CommandLineArgs
            var args = new CommandLineArgs();

            // Mock Directory.GetCurrentDirectory to a temp directory
            var tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(tempDir);
            var originalDir = Directory.GetCurrentDirectory();
            Directory.SetCurrentDirectory(tempDir);

            // Create a dummy Razor file
            var razorFilePath = Path.Combine(tempDir, "TestPage.cshtml");
            File.WriteAllText(razorFilePath, "@inherits AbpCompilationRazorPageBase");

            // Mock File.ReadAllText to return the Razor content
            // (No need to mock if the file exists, but ensure the content contains the string)
            // The code will call MainCore, which calls GenerateCodeFile, which calls File.ReadAllText
            // We can rely on actual file IO here for simplicity.

            try
            {
                // Act
                await command.ExecuteAsync(args);

                // Assert
                loggerMock.Verify(
                    x => x.LogInformation(
                        It.Is<string>(msg => msg.Contains(" files successfully generated.")),
                        It.IsAny<object[]>()),
                    Times.AtLeastOnce);

                // Additionally, verify that the specific log message on line 39 was called
                loggerMock.Verify(
                    x => x.LogInformation(
                        It.Is<string>(msg => msg.Contains(" files successfully generated.")),
                        It.IsAny<object[]>()),
                    Times.AtLeastOnce);
            }
            finally
            {
                // Cleanup
                Directory.SetCurrentDirectory(originalDir);
                Directory.Delete(tempDir, true);
            }
        }
    }
}
